import{_ as p,a0 as o,w as d,s as r,ao as i,I as l,x as a,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何使用 CGI 脚本生成网页 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 CGI 脚本生成网页 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 CGI 脚本生成网页 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 CGI 脚本生成网页 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171219 How to generate webpages using CGI scripts","title":"如何使用 CGI 脚本生成网页","tag":"201804","desc":""},"relativePath":"201804/20171219 How to generate webpages using CGI scripts.md","filePath":"[post].md"}'),h={name:"201804/20171219 How to generate webpages using CGI scripts.md"};function g(c,s,u,b,k,C){const e=o("Link");return d(),r("div",null,[s[17]||(s[17]=i(`<h1 id="如何使用-cgi-脚本生成网页" tabindex="-1">如何使用 CGI 脚本生成网页 <a class="header-anchor" href="#如何使用-cgi-脚本生成网页" aria-label="Permalink to “如何使用 CGI 脚本生成网页”">​</a></h1><blockquote><p>通用网关接口（CGI）提供了使用任何语言生成动态网站的简易方法。</p></blockquote><p>回到互联网的开端，当我第一次创建了我的第一个商业网站，生活是如此的美好。</p><p>我安装 Apache 并写了一些简单的 HTML 网页，网页上列出了一些关于我的业务的重要信息，比如产品概览以及如何联系我。这是一个静态网站，因为内容很少改变。由于网站的内容很少发生改变这一性质，因此维护起来也很简单。</p><h3 id="静态内容" tabindex="-1">静态内容 <a class="header-anchor" href="#静态内容" aria-label="Permalink to “静态内容”">​</a></h3><p>静态内容很简单，同时也很常见。让我们快速的浏览一些静态网页的例子。你不需要一个可运行网站来执行这些小实验，只需要把这些文件放到家目录，然后使用浏览器打开。你所看到的内容将和通过 Web 服务器提供这一文件看到的内容一样。</p><p>对于一个静态网站，你需要的第一件东西就是 <code>index.html</code> 文件，该文件通常放置在 <code>/var/www/html</code> 目录下。这个文件的内容可以非常简单，比如可以是像 “Hello, world” 这样一句短文本，没有任何 HTML 标记。它将简单的展示文本串内容。在你的家目录创建 <code>index.html</code> 文件，并添加 “hello, world” 作为内容（不需要引号）。在浏览器中通过下面的链接来打开这一文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>file:///home/&lt;你的家目录&gt;/index.html</span></span></code></pre></div><p>所以 HTML 不是必须的，但是，如果你有大量需要格式化的文本，那么，不用 HTML 编码的网页的结果将会令人难以理解。</p><p>所以，下一步就是通过使用一些 HTML 编码来提供格式化，从而使内容更加可读。下面这一命令创建了一个具有 HTML 静态网页所需要的绝对最小标记的页面。你也可以使用你最喜欢的编辑器来创建这一内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;&lt;h1&gt;Hello World&lt;/h1&gt;&quot; &gt; test1.html</span></span></code></pre></div><p>现在，再次查看 <code>index.html</code> 文件，将会看到和刚才有些不同。</p><p>当然，你可以在实际的内容行上添加大量的 HTML 标记，以形成更加完整和标准的网页。下面展示的是更加完整的版本，尽管在浏览器中会看到同样的内容，但这也为更加标准化的网站奠定了基础。继续在 <code>index.html</code> 中写入这些内容并通过浏览器查看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE HTML PUBLIC &quot;-//w3c//DD HTML 4.0//EN&quot;&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>&lt;title&gt;My Web Page&lt;/title&gt;</span></span>
<span class="line"><span>&lt;/head&gt;</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>&lt;h1&gt;Hello World&lt;/h1&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>我使用这些技术搭建了一些静态网站，但我的生活正在改变。</p><h3 id="动态网页" tabindex="-1">动态网页 <a class="header-anchor" href="#动态网页" aria-label="Permalink to “动态网页”">​</a></h3>`,16)),l("p",null,[s[2]||(s[2]=a("我找了一份新工作，这份工作的主要任务就是创建并维护用于一个动态网站的 CGI（",-1)),l("ruby",null,[t(e,{href:"https://en.wikipedia.org/wiki/Common_Gateway_Interface"},{default:n(()=>[...s[0]||(s[0]=[a("公共网关接口",-1)])]),_:1}),s[1]||(s[1]=l("rt",null,"Common Gateway InterfaceM",-1))]),s[3]||(s[3]=a("）代码。字面意思来看，动态意味着在浏览器中生成的网页所需要的 HTML 是由每次访问页面时不同的数据所生成的。这些数据包括网页表单中的用户输入，以用来在数据库中进行数据查找，结果数据被一些恰当的 HTML 包围着并展示在所请求的浏览器中。但是这不需要非常复杂。",-1))]),s[18]||(s[18]=i(`<p>通过使用 CGI 脚本，你可以创建一些简单或复杂的交互式程序，通过运行这些程序能够生成基于输入、计算、服务器的当前条件等改变的动态页面。有许多种语言可以用来写 CGI 脚本，在这篇文章中，我将谈到的是 Perl 和 Bash ，其他非常受欢迎的 CGI 语言包括 PHP 和 Python 。</p><p>这篇文章不会介绍 Apache 或其他任何 web 服务器的安装和配置。如果你能够访问一个你可以进行实验的 Web 服务器，那么你可以直接查看它们在浏览器中出现的结果。否则，你可以在命令行中运行程序来查看它们所创建的 HTML 文本。你也可以重定向 HTML 输出到一个文件中，然后通过浏览器查看结果文件。</p><h3 id="使用-perl" tabindex="-1">使用 Perl <a class="header-anchor" href="#使用-perl" aria-label="Permalink to “使用 Perl”">​</a></h3><p>Perl 是一门非常受欢迎的 CGI 脚本语言，它的优势是强大的文本操作能力。</p><p>为了使 CGI 脚本可执行，你需要在你的网站的 <code>httpd.conf</code> 中添加下面这行内容。这会告诉服务器可执行 CGI 文件的位置。在这次实验中，不必担心这个问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ScriptAlias /cgi-bin/ &quot;/var/www/cgi-bin/&quot;</span></span></code></pre></div><p>把下面的 Perl 代码添加到文件 <code>index.cgi</code>，在这次实验中，这个文件应该放在你的家目录下。如果你使用 Web 服务器，那么应把文件的所有者更改为 <code>apache.apache</code>，同时将文件权限设置为 755，因为无论位于哪，它必须是可执行的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/perl</span></span>
<span class="line"><span>print &quot;Content-type: text/html\\n\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;html&gt;&lt;body&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;h1&gt;Hello World&lt;/h1&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;Using Perl&lt;p&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;/body&gt;&lt;/html&gt;\\n&quot;;</span></span></code></pre></div><p>在命令行中运行这个程序并查看结果，它将会展示出它所生成的 HTML 内容</p><p>现在，在浏览器中查看 <code>index.cgi</code> 文件，你所看到的只是文件的内容。浏览器需要将它看做 CGI 内容，但是，Apache 不知道需要将这个文件作为 CGI 程序运行，除非 Apache 的配置中包括上面所展示的 <code>ScriptAlias</code> 定义。没有这一配置，Apache 只会简单地将文件中的数据发送给浏览器。如果你能够访问 Web 服务器，那么你可以将可执行文件放到 <code>/var/www/cgi-bin</code> 目录下。</p><p>如果想知道这个脚本的运行结果在浏览器中长什么样，那么，重新运行程序并把输出重定向到一个新文件，名字可以是任何你想要的。然后使用浏览器来查看这一文件，它包含了脚本所生成的内容。</p><p>上面这个 CGI 程序依旧生成静态内容，因为它总是生成相同的输出。把下面这行内容添加到 CGI 程序中 “Hello, world” 这一行后面。Perl 的 <code>system</code> 命令将会执行跟在它后面的 shell 命令，并把结果返回给程序。此时，我们将会通过 <code>free</code> 命令获得当前的内存使用量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>system &quot;free | grep Mem\\n&quot;;</span></span></code></pre></div><p>现在，重新运行这个程序，并把结果重定向到一个文件，在浏览器中重新加载这个文件。你将会看到额外的一行，它展示了系统的内存统计数据。多次运行程序并刷新浏览器，你将会发现，内存使用量应该是不断变化的。</p><h3 id="使用-bash" tabindex="-1">使用 Bash <a class="header-anchor" href="#使用-bash" aria-label="Permalink to “使用 Bash”">​</a></h3><p>Bash 可能是用于 CGI 脚本中最简单的语言。用 Bash 来进行 CGI 编程的最大优势是它能够直接访问所有的标准 GNU 工具和系统程序。</p><p>把已经存在的 <code>index.cgi</code> 文件重命名为 <code>Perl.index.cgi</code>，然后创建一个新的 \`index.cgi 文件并添加下面这些内容。记得设置权限使它可执行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>echo &quot;Content-type: text/html&quot;</span></span>
<span class="line"><span>echo &quot;&quot;</span></span>
<span class="line"><span>echo &#39;&lt;html&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;head&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=UTF-8&quot;&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;title&gt;Hello World&lt;/title&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;/head&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;body&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;h1&gt;Hello World&lt;/h1&gt;&lt;p&gt;&#39;</span></span>
<span class="line"><span>echo &#39;Using Bash&lt;p&gt;&#39;</span></span>
<span class="line"><span>free | grep Mem</span></span>
<span class="line"><span>echo &#39;&lt;/body&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;/html&gt;&#39;</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>在命令行中执行这个文件并查看输出，然后再次运行并把结果重定向到一个临时结果文件中。然后，刷新浏览器查看它所展示的网页是什么样子。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>创建能够生成许多种动态网页的 CGI 程序实际上非常简单。尽管这是一个很简单的例子，但是现在你应该看到一些可能性了。</p><hr>`,22)),l("p",null,[s[5]||(s[5]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/17/12/cgi-scripts"},{default:n(()=>[...s[4]||(s[4]=[a("https://opensource.com/article/17/12/cgi-scripts",-1)])]),_:1})]),l("p",null,[s[9]||(s[9]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[6]||(s[6]=[a("David Both",-1)])]),_:1}),s[10]||(s[10]=a(" 译者：",-1)),t(e,{href:"https://github.com/ucasFL"},{default:n(()=>[...s[7]||(s[7]=[a("ucasFL",-1)])]),_:1}),s[11]||(s[11]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[a("Linux中国",-1)])]),_:1}),s[16]||(s[16]=a(" 荣誉推出",-1))])])}const x=p(h,[["render",g]]);export{T as __pageData,x as default};
